const content = document.querySelector('#content');
const notice = document.querySelector('#notice');
const dialog = document.querySelector('#lead-dialog');
const detail = document.querySelector('#detail');
const account = document.querySelector('#account');
const state = { session: null, view: 'leads', leads: [], agents: [], metrics: null, settings: null, loadId: 0, detailId: 0, selected: null, query: '', status: '', assignee: '', page: 1, total: 0, pageSize: 25 };
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label = value => String(value ?? 'Unknown').replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
const show = value => value === null || value === undefined || value === '' ? 'Not recorded' : escape(value);
const date = value => { if (!value) return 'Not scheduled'; const d = new Date(value); return Number.isNaN(d.getTime()) ? 'Unknown' : new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(d); };
const owner = () => ['owner','admin'].includes(state.session?.user?.role);
const message = (text, error = false) => { notice.innerHTML = text ? `<div class="notice${error ? ' error' : ''}">${escape(text)}</div>` : ''; };
function clearPrivateState() { state.loadId++; state.detailId++; state.session = null; state.leads = []; state.agents = []; state.metrics = null; state.settings = null; state.selected = null; detail.replaceChildren(); if (dialog.open) dialog.close(); account.textContent = 'Secure workspace'; document.querySelectorAll('[data-view]').forEach(el => { if (el.dataset.view !== 'leads') el.hidden = true; }); }
function accessScreen(kind, text) { clearPrivateState(); content.setAttribute('aria-busy','false'); const denied = kind === 'denied'; content.innerHTML = `<div class="state-card"><div class="lock-icon" aria-hidden="true">◇</div><div class="eyebrow">Benefits with Veterans</div><h1>${denied ? 'Access is restricted' : kind === 'unavailable' ? 'Workspace not connected' : 'A secure space for your team'}</h1><p>${escape(text)}</p>${kind === 'unavailable' ? '<button class="btn" id="retry-session">Check connection again</button>' : '<a class="btn" href="/api/auth/google">Continue with Google Workspace <span aria-hidden="true">↗</span></a>'}<p class="quiet" style="margin-top:24px">Invitation required. Your account must have an active, explicitly assigned agency role.</p><a class="quiet" href="/">Return to the public website</a></div>`; document.querySelector('#retry-session')?.addEventListener('click', boot); }
async function api(path, options = {}) {
 const headers = { Accept:'application/json', ...(options.body ? {'Content-Type':'application/json','X-CSRF-Token':state.session?.csrfToken || ''} : {}), ...options.headers };
 const controller = new AbortController(); const timer = setTimeout(()=>controller.abort(),15000);
 try {
  const response = await fetch(path,{credentials:'same-origin',cache:'no-store',...options,headers,signal:controller.signal});
  let body; try { body = await response.json(); } catch(error) { if (controller.signal.aborted) throw error; body = {}; }
  if (!response.ok) { const error = new Error(body.error?.message || body.message || (response.status === 503 ? 'The secure workspace is not configured yet.' : 'The request could not be completed. Please try again.')); error.status = response.status; if (response.status === 401) accessScreen('signedout','Your session has expired. Sign in again to continue.'); throw error; }
  return body;
 } catch(error) {
  if(controller.signal.aborted || error instanceof TypeError) throw new Error(options.method && options.method !== 'GET' ? 'We could not confirm this change. Refresh and check the record before trying again; the server may have saved it.' : 'The secure connection timed out or was interrupted. Please try again.');
  throw error;
 } finally { clearTimeout(timer); }
}

const heading = (eyebrow,title,description) => `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><span class="badge muted">${owner() ? escape(label(state.session.user.role)) + ' workspace' : 'Assigned leads only'}</span></div>`;
const metric = (name,value,note = '') => `<div class="metric"><div class="metric-label">${escape(name)}</div><div class="metric-value">${typeof value === 'number' ? value.toLocaleString() : '—'}</div><div class="metric-note">${escape(note)}</div></div>`;
function loading(text) { content.setAttribute('aria-busy','true'); content.innerHTML = `<div class="state-card"><div class="loading-ring" aria-hidden="true"></div><h2>${escape(text)}</h2><p>Retrieving authorized records securely.</p></div>`; }
function loadError(error) { content.setAttribute('aria-busy','false'); content.innerHTML = `<div class="state-card"><h1>${error.status === 403 ? 'This view is restricted' : 'We couldn’t load this view'}</h1><p>${escape(error.message)}</p><button class="btn" id="reload-view">Try again</button></div>`; document.querySelector('#reload-view').addEventListener('click',()=>navigate(state.view)); }
function renderAccount() { const u = state.session.user; account.innerHTML = `<div>${escape(u.name || u.email)}<small>${escape(label(u.role))}</small></div><button id="logout">Sign out</button>`; document.querySelector('#logout').addEventListener('click', async event => { event.target.disabled = true; try { await api('/api/auth/logout',{method:'POST',body:'{}'}); accessScreen('signedout','You have been signed out. Sign in with your invited Google Workspace account to continue.'); } catch(error) { if(state.session) { event.target.disabled = false; message(`Sign out could not be confirmed. ${error.message}`,true); } } }); document.querySelectorAll('[data-view]').forEach(el => { el.hidden = el.dataset.view !== 'leads' && !owner(); }); }
async function boot() { const request = ++state.loadId; message(''); loading('Opening your workspace'); try { const session = await api('/api/admin/session'); if (request !== state.loadId) return; state.session = session; if (!['owner','admin','agent'].includes(state.session?.user?.role)) return accessScreen('denied','Your account does not have a supported agency role. Ask the agency owner to review your invitation and access.'); renderAccount(); await navigate('leads'); } catch(error) { if (error.status === 401) return; accessScreen(error.status === 403 ? 'denied' : 'unavailable',error.message); } }

document.querySelectorAll('[data-view]').forEach(button => button.addEventListener('click',()=>navigate(button.dataset.view)));
dialog.addEventListener('close',()=>{ state.detailId++; state.selected = null; detail.replaceChildren(); });
window.addEventListener('pagehide',clearPrivateState);
window.addEventListener('pageshow',event=>{if(event.persisted) boot();});
const statuses = ['new','contacted','qualified','application','sold','closed','archived'];
async function navigate(view) {
 if(!state.session || (view !== 'leads' && !owner()))return;
 state.view=view;const request=++state.loadId;message('');loading(view === 'leads' ? 'Loading your leads' : `Loading ${view}`);
 document.querySelectorAll('[data-view]').forEach(el=>{const active=el.dataset.view===view;el.classList.toggle('active',active);active?el.setAttribute('aria-current','page'):el.removeAttribute('aria-current');});
 try {
 if(view==='leads'){const params=new URLSearchParams({page:String(state.page),search:state.query,status:state.status});const [list,metrics]=await Promise.all([api(`/api/admin/leads?${params}`),api('/api/admin/metrics')]);if(request!==state.loadId||!state.session)return;state.leads=list.leads;state.total=list.total;state.pageSize=list.pageSize;state.metrics=metrics;renderLeads();}
 else if(view==='reports'){const data=await api('/api/admin/metrics');if(request!==state.loadId||!state.session)return;state.metrics=data;renderReports();}
 else if(view==='team'){const data=await api('/api/admin/users');if(request!==state.loadId||!state.session)return;state.agents=data.users;renderTeam();}
 else {const data=await api('/api/admin/settings');if(request!==state.loadId||!state.session)return;state.settings=data;renderSettings();}
 content.setAttribute('aria-busy','false');
 }catch(error){if(request===state.loadId&&state.session)loadError(error);}
}
function summaryMetrics(){const m=state.metrics||{};return `<div class="metric-grid">${metric('Total leads',m.total,'Within your authorized view')}${metric('New inquiries',m.new,'Ready for a thoughtful first contact')}${metric('Follow-ups due',m.followUpDue,'Only recorded follow-up dates')}${metric('Appointment requests',m.appointmentRequested,'Requests, not confirmed bookings')}</div>`;}
function renderLeads(){content.innerHTML=heading('Your next meaningful conversation','Lead workspace',owner()?'A clear view of your agency’s inquiries, ownership, and next steps.':'Your assigned inquiries, organized for thoughtful follow-through.')+summaryMetrics()+`<section class="panel"><div class="panel-header"><div><h2>${owner()?'Agency leads':'Assigned to you'}</h2><span class="quiet">${state.total.toLocaleString()} authorized records</span></div><button class="btn secondary small" id="refresh-leads">Refresh</button></div><form id="filters" class="toolbar"><label>Search by name<input id="search" type="search" maxlength="100" value="${escape(state.query)}" placeholder="Find a lead" autocomplete="off"></label><label>Status<select id="status-filter"><option value="">All statuses</option>${statuses.map(s=>`<option value="${s}" ${state.status===s?'selected':''}>${label(s)}</option>`).join('')}</select></label><button class="btn" type="submit">Apply filters</button></form>${state.leads.length?`<div class="table-wrap"><table><thead><tr><th scope="col">Lead / interest</th><th scope="col">Location</th><th scope="col">Status</th><th scope="col">Assignment</th><th scope="col">Received</th></tr></thead><tbody>${state.leads.map(l=>`<tr><td><button class="lead-name" data-lead="${escape(l.id)}">${show(l.name)}</button><span class="subtext">${escape(label(l.product))}</span></td><td>${show(l.state)}</td><td><span class="badge ${l.do_not_contact?'danger':l.status==='new'?'warn':'muted'}">${l.do_not_contact?'Do not contact':escape(label(l.status))}</span></td><td><span class="badge ${l.assigned_to?'':'warn'}">${l.assigned_to?'Assigned':'Unassigned'}</span></td><td>${escape(date(l.created_at))}</td></tr>`).join('')}</tbody></table></div><div class="panel-header" style="margin:20px 0 0"><span class="quiet">Page ${state.page} of ${Math.max(1,Math.ceil(state.total/state.pageSize))}</span><div><button class="btn secondary small" id="previous" ${state.page<=1?'disabled':''}>Previous</button> <button class="btn secondary small" id="next" ${state.page*state.pageSize>=state.total?'disabled':''}>Next</button></div></div>`:`<div class="empty"><strong>${state.query||state.status?'No matching leads':'A fresh start, with room to grow.'}</strong>${state.query||state.status?'Try a different search or clear your filters.':owner()?'New inquiries will appear after secure intake is connected and approved.':'Leads will appear when an authorized owner assigns them to you.'}</div>`}</section><p class="quiet">Application and sold counts appear only when explicitly recorded. Missing information is shown as unknown.</p>`;
 document.querySelector('#filters').addEventListener('submit',e=>{e.preventDefault();state.query=document.querySelector('#search').value.trim();state.status=document.querySelector('#status-filter').value;state.page=1;navigate('leads');});document.querySelector('#refresh-leads').addEventListener('click',()=>navigate('leads'));document.querySelectorAll('[data-lead]').forEach(el=>el.addEventListener('click',()=>openLead(el.dataset.lead)));document.querySelector('#previous')?.addEventListener('click',()=>{state.page--;navigate('leads');});document.querySelector('#next')?.addEventListener('click',()=>{state.page++;navigate('leads');});
}
const fact=(name,value)=>`<div><dt>${escape(name)}</dt><dd>${show(value)}</dd></div>`;
async function openLead(id){const request=++state.detailId;state.selected=id;detail.innerHTML=`<div class="dialog-heading"><h2 id="detail-title">Loading lead</h2><button class="close-btn" aria-label="Close lead" data-close>×</button></div><div class="empty">Retrieving this authorized record…</div>`;bindClose();if(!dialog.open)dialog.showModal();try{const data=await api(`/api/admin/leads/${encodeURIComponent(id)}`);if(request!==state.detailId||!state.session||!dialog.open)return;renderDetail(data);}catch(error){if(request!==state.detailId||!state.session)return;detail.innerHTML=`<div class="dialog-heading"><h2 id="detail-title">${error.status===403||error.status===404?'Lead unavailable':'Unable to load lead'}</h2><button class="close-btn" data-close aria-label="Close lead">×</button></div><p>${escape(error.message)}</p>`;bindClose();}}
function bindClose(){detail.querySelector('[data-close]')?.addEventListener('click',()=>dialog.close());}
function localDate(value){if(!value)return '';const d=new Date(value);if(Number.isNaN(d.getTime()))return '';return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function eventDetail(event) {
 const d=event.detail || {}; const parts=[];
 if(d.body || event.body || event.note) parts.push(show(d.body || event.body || event.note));
 if(d.status) parts.push('Status: '+escape(label(d.status)));
 if(Object.hasOwn(d,'do_not_contact')) parts.push('Do not contact: '+(d.do_not_contact?'Yes':'No'));
 if(Object.hasOwn(d,'follow_up_at')) parts.push('Follow-up: '+escape(date(d.follow_up_at)));
 if(d.reason) parts.push('Reason: '+show(d.reason));
 return parts.length ? '<div>'+parts.join('<br>')+'</div>' : '';
}
function renderDetail(data){const l=data.lead;const consent=data.consents||[];const events=data.events||[];detail.innerHTML=`<div class="dialog-heading"><div><div class="eyebrow">Private lead record</div><h2 id="detail-title">${show(l.name)}</h2><span class="badge ${l.do_not_contact?'danger':'muted'}">${l.do_not_contact?'Do not contact':escape(label(l.status))}</span></div><button class="close-btn" data-close aria-label="Close lead">×</button></div><div id="detail-message" role="status" aria-live="polite"></div><div class="split"><div><section class="panel"><h3>Contact & interest</h3><dl class="facts">${fact('Email',l.email)}${fact('Phone',l.phone)}${fact('State',l.state)}${fact('Age range',l.age_range)}${fact('Product interest',label(l.product))}${fact('Coverage goal',l.interest)}${fact('Planning budget',l.budget)}${fact('Preferred contact',l.preferred_contact)}${fact('Request type',l.intent==='appointment'?'Appointment requested':'Quote inquiry')}${fact('Received',date(l.created_at))}</dl>${l.do_not_contact?'<p class="notice error" style="margin-top:20px">Do not contact. Honor this preference before any outreach.</p>':''}</section><section class="panel"><h3>Source & attribution</h3><dl class="facts">${fact('Source page',l.source_path)}${fact('Source',l.utm?.source)}${fact('Medium',l.utm?.medium)}${fact('Campaign',l.utm?.campaign)}${fact('Term',l.utm?.term)}${fact('Content',l.utm?.content)}</dl></section><section class="panel"><h3>Consent record</h3><p class="quiet">Read-only evidence captured at submission. Contact consent does not establish product eligibility.</p>${consent.length?consent.map(c=>`<div class="consent-box"><p><strong>${show(c.version||c.consent_version||'Recorded consent')}</strong> · ${escape(date(c.created_at||c.recorded_at))}</p><p>${show(c.contact_text||c.text||c.consent_text)}</p>${c.marketing_text?`<p>${show(c.marketing_text)}</p>`:''}<p>Contact: ${c.contact===true||c.contact_consent===true?'Accepted':'See stored record'} · Marketing: ${c.marketing===true||c.marketing_consent===true?'Accepted':'Not opted in'}</p></div>`).join(''):'<div class="consent-box">No consent evidence was returned. Verify authorization before outreach.</div>'}</section></div><div><section class="panel"><h3>Next steps</h3><form id="lead-update"><label class="field">Lead status<select name="status">${statuses.map(s=>`<option value="${s}" ${l.status===s?'selected':''}>${label(s)}</option>`).join('')}</select></label><label class="field">Follow-up date & time (your local time)<input name="follow_up_at" type="datetime-local" value="${escape(localDate(l.follow_up_at))}"></label><label class="field check"><input type="checkbox" name="do_not_contact" ${l.do_not_contact?'checked':''}> Do not contact</label><p class="quiet">Only select Application or Sold when that outcome is verified. Closed does not mean a policy was sold.</p><button class="btn" type="submit">Save changes</button></form></section>${owner()?`<section class="panel"><h3>Assignment</h3><p class="quiet">${l.assigned_to?'This lead has an assigned agent.':'This lead is currently unassigned.'} The server checks verified eligibility before every assignment.</p><button class="btn secondary" id="show-assignment">Review eligible team</button><div id="assignment"></div></section>`:''}<section class="panel"><h3>Notes & activity</h3><form id="add-note"><label class="field">Add an internal note<textarea name="body" required maxlength="2000" placeholder="A concise update or next step"></textarea></label><p class="quiet">Do not add health, financial account, identity, or other sensitive personal details.</p><button class="btn secondary" type="submit">Save note</button></form><div class="divider"></div>${events.length?`<ul class="activity">${events.map(e=>`<li><strong>${escape(label(e.event||e.type||e.event_type||e.action))}</strong>${eventDetail(e)}<time>${escape(date(e.created_at))}</time></li>`).join('')}</ul>`:'<p class="quiet">No activity has been recorded yet.</p>'}</section></div></div>`;
 bindClose();document.querySelector('#lead-update').addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.target);const follow=form.get('follow_up_at');saveLead(l,e.submitter,`/api/admin/leads/${encodeURIComponent(l.id)}`,'PATCH',{status:form.get('status'),follow_up_at:follow?new Date(follow).toISOString():null,do_not_contact:form.get('do_not_contact')==='on'},'Lead changes saved.');});document.querySelector('#add-note').addEventListener('submit',e=>{e.preventDefault();saveLead(l,e.submitter,`/api/admin/leads/${encodeURIComponent(l.id)}/notes`,'POST',{body:new FormData(e.target).get('body')},'Note saved.');});document.querySelector('#show-assignment')?.addEventListener('click',e=>loadAssignment(l,e.target));
}
async function saveLead(lead,button,path,method,body,success){button.disabled=true;const request=state.detailId;try{await api(path,{method,body:JSON.stringify(body)});if(request!==state.detailId||!state.session)return;await openLead(lead.id);await navigate('leads');message(success);}catch(error){if(request===state.detailId&&state.session){document.querySelector('#detail-message').innerHTML=`<p class="notice error">${escape(error.message)}</p>`;button.disabled=false;}}}
async function loadAssignment(lead,button){button.disabled=true;const selected=state.detailId;try{const data=await api('/api/admin/users');if(selected!==state.detailId||!state.session)return;const agents=data.users.filter(u=>u.role==='agent');document.querySelector('#assignment').innerHTML=agents.length?`<form id="assign-form"><label class="field">Team member<select name="agentId" required><option value="">Choose an agent</option>${agents.map(a=>`<option value="${escape(a.user_id)}" ${!a.verified||a.status!=='active'?'disabled':''}>${escape(a.email)}${!a.verified||a.status!=='active'?' — not verified / active':''}</option>`).join('')}</select></label><div class="quiet">${agents.map(a=>`<p>${escape(a.email)}: ${a.eligibility?.length?escape(a.eligibility.map(e=>[e.state,e.product,e.carrier,e.verified&&e.active?'Verified and active':'Unverified / inactive',e.license_expires_at?'License expires '+date(e.license_expires_at):'Expiry unknown'].filter(Boolean).join(' / ')).join('; ')):'No verified eligibility on file'}</p>`).join('')}</div><label class="field">Assignment reason<textarea name="reason" required maxlength="500" placeholder="Explain this assignment"></textarea></label><button class="btn" type="submit">Confirm assignment</button></form>`:'<p class="quiet">No agent accounts are available. Invite and verify an agent before assigning leads.</p>';document.querySelector('#assign-form')?.addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.target);saveLead(lead,e.submitter,`/api/admin/leads/${encodeURIComponent(lead.id)}/assign`,'POST',{agentId:form.get('agentId'),expectedAssignee:lead.assigned_to||null,reason:form.get('reason')},'Assignment saved after eligibility verification.');});}catch(error){if(selected===state.detailId&&state.session){document.querySelector('#assignment').innerHTML=`<p class="inline-error">${escape(error.message)}</p>`;button.disabled=false;}}}
function breakdown(title,data,key){const entries=Array.isArray(data)?data.map(row=>[row[key]||row.name||row.label||row.id||'Unknown',row.count??row.total]):data&&typeof data==='object'?Object.entries(data):[];return `<section class="panel"><h2>${title}</h2>${entries.length?`<div class="table-wrap"><table><thead><tr><th scope="col">${title.replace('By ','')}</th><th scope="col">Leads</th></tr></thead><tbody>${entries.map(([name,count])=>`<tr><td>${escape(name)}</td><td>${typeof count==='number'?count.toLocaleString():'Unknown'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="quiet">No recorded breakdown is available yet.</p>'}</section>`;}
function renderReports(){const m=state.metrics||{};content.innerHTML=heading('Recorded outcomes','Performance','Understand the work behind every conversation, using only recorded agency activity.')+summaryMetrics()+`<div class="metric-grid">${metric('Applications',m.application,'Explicitly recorded application status')}${metric('Sold',m.sold,'Explicitly recorded sold status')}${metric('Qualified',m.qualified,'Current qualified status')}${metric('Unassigned',m.unassigned,'Needs an eligible agent')}</div><div class="split">${breakdown('By source',m.bySource,'source')}${breakdown('By campaign',m.byCampaign,'campaign')}</div>${breakdown('By agent',m.byAgent,'agent')}<p class="section-note">These are workflow counts, not carrier-verified production reports. Unknown attribution remains unknown. An appointment request is not a confirmed appointment.</p>`;}
function renderTeam(){content.innerHTML=heading('An intentional team','Team & access','Invite the right people. Grant explicit roles. Verify eligibility before assigning leads.')+`<section class="panel"><div class="panel-header"><h2>Agency members</h2><span class="badge muted">${state.agents.length} members</span></div>${state.agents.length?`<div class="table-wrap"><table><thead><tr><th scope="col">Account</th><th scope="col">Role</th><th scope="col">Access</th><th scope="col">Eligibility</th></tr></thead><tbody>${state.agents.map(a=>`<tr><td>${show(a.email)}</td><td>${escape(label(a.role))}</td><td><span class="badge ${a.status==='active'&&a.verified?'':'warn'}">${escape(label(a.status))}${a.verified?' · Verified':' · Unverified'}</span></td><td>${a.eligibility?.length?`${a.eligibility.length} eligibility records`:'Not verified'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>No team members returned</strong>Only members of your agency appear here.</div>'}</section><div class="split"><section class="panel"><h2>Invite a team member</h2><form id="invite-form"><label class="field">Google Workspace email<input type="email" name="email" required maxlength="254" autocomplete="off" placeholder="name@your-agency.com"></label><label class="field">Role<select name="role"><option value="agent">Agent · assigned leads only</option>${state.session.user.role==='owner'?'<option value="admin">Admin · agency-wide management</option>':''}</select></label><p class="quiet">An invitation records access intent. Identity, active membership, and role are checked at sign-in. A matching email domain alone never grants access.</p><p class="section-note">Invitations are recorded as pending. Email delivery is not connected; creating an invitation does not send an email.</p><button class="btn" type="submit">Create pending invitation</button><div id="invite-result" role="status" aria-live="polite"></div></form></section><section class="panel"><h2>Eligibility before ownership</h2><p>Assignment requires verified, current state and product eligibility. Missing licensing or appointment information blocks assignment.</p><p class="quiet">An account or invitation is not proof of licensing. No actual staff accounts are pre-seeded.</p><div class="divider"></div><h3>Manager scope</h3><p class="quiet">Team-manager access is unavailable until a specific team scope is implemented and approved. Unsupported roles cannot enter this workspace.</p></section></div>`;
 document.querySelector('#invite-form').addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.target);const button=event.submitter;button.disabled=true;const request=state.loadId;try{const data=await api('/api/admin/invites',{method:'POST',body:JSON.stringify({email:form.get('email'),role:form.get('role')})});if(request!==state.loadId||!state.session)return;document.querySelector('#invite-result').innerHTML=`<p class="notice">Pending invitation recorded for ${escape(data.invitation.email)}. ${data.delivery==='not_sent'?'No email was sent.':'Check the recorded delivery status before contacting the recipient.'}</p>`;event.target.reset();}catch(error){if(request===state.loadId&&state.session)document.querySelector('#invite-result').innerHTML=`<p class="notice error">${escape(error.message)}</p>`;}finally{if(button.isConnected)button.disabled=false;}});
}
function renderSettings(){const s=state.settings;content.innerHTML=heading('Thoughtful by default','Agency settings','A transparent view of the safeguards behind your workspace.')+`<div class="split"><section class="panel"><h2>Workspace configuration</h2><dl class="facts">${fact('Agency',s.agency?.name)}${fact('Environment',label(s.mode))}${fact('Sign-in','Invite-only Google Workspace')}${fact('Access model','Explicit agency roles')}</dl><div class="divider"></div><p class="quiet">Changes to identity, credentials, eligibility, and retention require an approved administrative process.</p></section><section class="panel"><h2>Lead routing</h2><span class="badge warn">Manual assignment</span><p style="margin-top:20px">Each assignment is checked against active, verified eligibility for the lead’s state and product.</p><label class="check"><input type="checkbox" disabled> Automatic round-robin assignment</label><p class="quiet">Disabled pending owner approval, verified credentials, and an approved routing policy.</p></section><section class="panel"><h2>Email notifications</h2><span class="badge warn">${s.notifications?.enabled?'Check provider configuration':'Delivery not enabled'}</span><p style="margin-top:20px">A queued notification is not a sent email. Delivery requires configured credentials and approval.</p><p class="quiet">Do-not-contact preferences must be honored. Review notification status and the delivery provider before relying on outreach.</p></section><section class="panel"><h2>Privacy & retention</h2><span class="badge muted">${escape(label(s.retention?.status||'approval_required'))}</span><p style="margin-top:20px">Lead and consent records stay in the authenticated workspace. Client information is not stored in browser local storage.</p><p class="quiet">Retention and deletion policies require approval before activation.</p></section></div>`;}
boot();
